// apps/lambdas/uploads-lambda/__tests__/presignUpload.test.ts
import { describe, it, expect, vi, beforeEach } from 'vitest'
import type { APIGatewayProxyEvent } from 'aws-lambda'

const mockPresignPutUrl = vi.fn()
vi.mock('../src/lib/s3', () => ({
  buildDocumentKey: (userId: string, name: string) => `users/${userId}/documents/${name}`,
  presignPutUrl: mockPresignPutUrl,
  PRESIGN_EXPIRES_IN: 600,
}))

import { presignUpload } from '../src/routes/presignUpload'

function makeEvent(body: object, userId = 'user-1'): APIGatewayProxyEvent {
  return {
    body: JSON.stringify(body),
    httpMethod: 'POST',
    path: '/uploads/presign',
    requestContext: { authorizer: { userId } },
  } as unknown as APIGatewayProxyEvent
}

describe('presignUpload', () => {
  beforeEach(() => vi.clearAllMocks())

  it('returns uploadUrl + key + expiresIn for valid request', async () => {
    mockPresignPutUrl.mockResolvedValue('https://s3.example.com/put-url')
    const res = await presignUpload(makeEvent({ name: 'lab.pdf', contentType: 'application/pdf' }))
    expect(res.statusCode).toBe(200)
    const body = JSON.parse(res.body)
    expect(body.data.uploadUrl).toBe('https://s3.example.com/put-url')
    expect(body.data.key).toContain('user-1')
    expect(body.data.expiresIn).toBe(600)
  })

  it('throws 400 when contentType is missing', async () => {
    await expect(presignUpload(makeEvent({ name: 'lab.pdf' }))).rejects.toMatchObject({
      statusCode: 400,
    })
  })

  it('throws 401 when no userId in authorizer', async () => {
    await expect(
      presignUpload(makeEvent({ name: 'lab.pdf', contentType: 'application/pdf' }, undefined as unknown as string))
    ).rejects.toMatchObject({ statusCode: 401 })
  })
})
