`createDispatcher` is the central router used by all 9 lambdas. No dedicated test exists — only the `responseContract.test.ts` touches adjacent behavior.

**Missing test scenarios:**
- Path parameter extraction (`:id` → `event.pathParameters`)
- `/v1`-prefix stripping vs bare-prefix stripping
- OPTIONS preflight returns 200 + CORS headers
- 404 for unmatched route
- 4xx error objects serialized correctly (typed `AppError` vs legacy `{statusCode, message}`)
- Response contract validation fires in non-production, suppressed in production

```ts
// apps/lambdas/_shared/__tests__/dispatcher.test.ts
import { describe, it, expect, vi } from 'vitest'
import type { APIGatewayProxyEvent } from 'aws-lambda'
import { createDispatcher } from '../dispatcher'
import type { LambdaManifest } from '../defineRoute'
import { BadRequestError, NotFoundError } from '@lifeos/utils'

function makeManifest(overrides?: Partial<LambdaManifest>): LambdaManifest {
  return {
    name: 'test-lambda',
    tag: 'Test',
    basePath: '/test',
    description: '',
    routes: [
      {
        method: 'GET',
        path: '/items/:id',
        operationId: 'test.getItem',
        handler: async (e) => ({
          statusCode: 200,
          body: JSON.stringify({ success: true, data: { id: e.pathParameters?.id } }),
          headers: {},
        }),
      },
    ],
    ...overrides,
  }
}

function makeEvent(method: string, path: string): APIGatewayProxyEvent {
  return {
    httpMethod: method,
    path,
    body: null,
    requestContext: { authorizer: { userId: 'u1' } },
  } as unknown as APIGatewayProxyEvent
}

describe('createDispatcher', () => {
  it('extracts :id path parameter from route match', async () => {
    const handler = createDispatcher(makeManifest())
    const res = await handler(makeEvent('GET', '/test/items/abc-123'))
    expect(res.statusCode).toBe(200)
    expect(JSON.parse(res.body).data.id).toBe('abc-123')
  })

  it('strips /v1 prefix before matching', async () => {
    const handler = createDispatcher(makeManifest())
    const res = await handler(makeEvent('GET', '/v1/test/items/xyz'))
    expect(res.statusCode).toBe(200)
  })

  it('returns 404 for unmatched route', async () => {
    const handler = createDispatcher(makeManifest())
    const res = await handler(makeEvent('GET', '/test/unknown'))
    expect(res.statusCode).toBe(404)
  })

  it('returns 200 with CORS headers for OPTIONS preflight', async () => {
    const handler = createDispatcher(makeManifest())
    const res = await handler({ ...makeEvent('OPTIONS', '/test/items/1') })
    expect(res.statusCode).toBe(200)
    expect(res.headers?.['Access-Control-Allow-Origin']).toBeDefined()
  })

  it('serializes AppError to correct statusCode + message', async () => {
    const manifest = makeManifest({
      routes: [{
        method: 'GET', path: '/fail', operationId: 'test.fail',
        handler: async () => { throw new BadRequestError('bad field', { field: 'name' }) },
      }],
    })
    const handler = createDispatcher(manifest)
    const res = await handler(makeEvent('GET', '/test/fail'))
    expect(res.statusCode).toBe(400)
    expect(JSON.parse(res.body).error).toBe('bad field')
  })

  it('returns 500 with generic message in production', async () => {
    process.env.NODE_ENV = 'production'
    const manifest = makeManifest({
      routes: [{
        method: 'GET', path: '/boom', operationId: 'test.boom',
        handler: async () => { throw new Error('internal secret') },
      }],
    })
    const handler = createDispatcher(manifest)
    const res = await handler(makeEvent('GET', '/test/boom'))
    expect(res.statusCode).toBe(500)
    expect(JSON.parse(res.body).error).toBe('Internal server error')
    process.env.NODE_ENV = 'test'
  })
})
