// packages/utils/src/__tests__/errors.test.ts
import { describe, it, expect } from 'vitest'
import {
  AppError, BadRequestError, UnauthorizedError, ForbiddenError,
  NotFoundError, ConflictError, ValidationError, RateLimitError,
  InternalServerError, isHttpError,
} from '../errors'

describe('AppError subclasses', () => {
  it.each([
    [BadRequestError, 400],
    [UnauthorizedError, 401],
    [ForbiddenError, 403],
    [NotFoundError, 404],
    [ConflictError, 409],
    [RateLimitError, 429],
    [InternalServerError, 500],
  ])('%s has correct statusCode', (Ctor, code) => {
    expect(new Ctor().statusCode).toBe(code)
  })

  it('ValidationError carries fields on details', () => {
    const e = new ValidationError('bad', { name: 'required' })
    expect(e.statusCode).toBe(422)
    expect(e.details).toEqual({ name: 'required' })
  })

  it('AppError name matches class name', () => {
    expect(new BadRequestError().name).toBe('BadRequestError')
  })
})

describe('isHttpError', () => {
  it('returns true for AppError instances', () => {
    expect(isHttpError(new NotFoundError())).toBe(true)
  })

  it('returns true for legacy {statusCode, message} plain objects', () => {
    expect(isHttpError({ statusCode: 409, message: 'conflict' })).toBe(true)
  })

  it('returns false for plain Error', () => {
    expect(isHttpError(new Error('oops'))).toBe(false)
  })

  it('returns false for null / primitive', () => {
    expect(isHttpError(null)).toBe(false)
    expect(isHttpError('string')).toBe(false)
  })
})
