// packages/utils/src/__tests__/lambdaUtils.test.ts
import { describe, it, expect } from 'vitest'
import { validateBody, getUserId, ok, error, cors } from '../lambdaUtils'
import { z } from 'zod'
import type { APIGatewayProxyEvent } from 'aws-lambda'

function makeEvent(body: unknown, userId?: string): APIGatewayProxyEvent {
  return {
    body: body !== undefined ? JSON.stringify(body) : null,
    requestContext: { authorizer: userId ? { userId } : {} },
  } as unknown as APIGatewayProxyEvent
}

describe('validateBody', () => {
  const schema = z.object({ name: z.string() })

  it('parses valid body', () => {
    expect(validateBody(makeEvent({ name: 'Alice' }), schema)).toEqual({ name: 'Alice' })
  })

  it('throws 400 BadRequestError on invalid body', () => {
    expect(() => validateBody(makeEvent({}), schema)).toThrow(expect.objectContaining({ statusCode: 400 }))
  })

  it('treats null body as empty object (no crash)', () => {
    expect(() => validateBody(makeEvent(null), schema)).toThrow(expect.objectContaining({ statusCode: 400 }))
  })
})

describe('getUserId', () => {
  it('returns userId from authorizer', () => {
    expect(getUserId(makeEvent(null, 'user-abc'))).toBe('user-abc')
  })

  it('throws 401 when userId is absent', () => {
    expect(() => getUserId(makeEvent(null))).toThrow(expect.objectContaining({ statusCode: 401 }))
  })
})

describe('ok / error', () => {
  it('ok wraps data in { success: true, data }', () => {
    const res = ok({ foo: 1 })
    expect(res.statusCode).toBe(200)
    expect(JSON.parse(res.body)).toEqual({ success: true, data: { foo: 1 } })
  })

  it('error wraps message in { success: false, error }', () => {
    const res = error(404, 'not found')
    expect(res.statusCode).toBe(404)
    expect(JSON.parse(res.body)).toEqual({ success: false, error: 'not found' })
  })
})

describe('cors', () => {
  it('never returns wildcard origin', () => {
    expect(cors()['Access-Control-Allow-Origin']).not.toBe('*')
  })

  it('includes Access-Control-Max-Age for preflight caching', () => {
    expect(cors()['Access-Control-Max-Age']).toBeDefined()
  })
})
