// packages/utils/src/__tests__/performance.test.ts
import { describe, it, expect } from 'vitest'
import { calculateE1RM, calculateVolume, computeYearPercentage, computeBestStretchDays } from '../performance'

describe('calculateE1RM', () => {
  it('returns weight for 1 rep (identity)', () => {
    expect(calculateE1RM(100, 1)).toBe(100)
  })

  it('uses Epley formula for > 1 rep', () => {
    // 100 * (1 + 5/30) = 116.67
    expect(calculateE1RM(100, 5)).toBeCloseTo(116.67, 1)
  })

  it('returns 0 for zero weight or zero reps', () => {
    expect(calculateE1RM(0, 5)).toBe(0)
    expect(calculateE1RM(100, 0)).toBe(0)
  })
})

describe('calculateVolume', () => {
  it('sums reps * weight for completed sets only', () => {
    const sets = [
      { actualReps: 10, weight: '50', completed: true },
      { actualReps: 10, weight: '50', completed: false }, // skipped
    ]
    expect(calculateVolume(sets)).toBe(500)
  })

  it('returns 0 for empty sets', () => {
    expect(calculateVolume([])).toBe(0)
  })

  it('handles null reps/weight gracefully', () => {
    expect(calculateVolume([{ actualReps: null, weight: null, completed: true }])).toBe(0)
  })
})

describe('computeYearPercentage', () => {
  it('caps at 100 even if over-performing', () => {
    const { percent } = computeYearPercentage(9999, 3, new Date('2026-12-31'))
    expect(percent).toBe(100)
  })

  it('returns 0 for weeklyTarget of 0', () => {
    expect(computeYearPercentage(10, 0).percent).toBe(0)
  })
})

describe('computeBestStretchDays', () => {
  it('counts consecutive days correctly', () => {
    const sessions = [
      { completedAt: '2026-05-01T10:00:00Z' },
      { completedAt: '2026-05-02T10:00:00Z' },
      { completedAt: '2026-05-03T10:00:00Z' },
      { completedAt: '2026-05-05T10:00:00Z' }, // gap
    ]
    expect(computeBestStretchDays(sessions as never)).toBe(3)
  })

  it('ignores sessions without completedAt', () => {
    expect(computeBestStretchDays([{ completedAt: null }] as never)).toBe(0)
  })

  it('returns 0 for empty array', () => {
    expect(computeBestStretchDays([])).toBe(0)
  })
})
