import { describe, it, expect } from 'vitest'
import { deriveBMI, bmiBand, suggestedTargetWeightKg } from './derivePrefill'
import type { OnboardingWizardState } from './types'

describe('deriveBMI', () => {
  it('calculates BMI correctly', () => {
    // 70kg / (1.75m)^2 = 22.9
    expect(deriveBMI(175, 70)).toBeCloseTo(22.9, 0)
  })
  it('returns null for missing height or weight', () => {
    expect(deriveBMI(undefined, 70)).toBeNull()
    expect(deriveBMI(175, undefined)).toBeNull()
    expect(deriveBMI(0, 70)).toBeNull()
  })
})

describe('bmiBand', () => {
  it.each([
    [17, 'underweight'],
    [22, 'normal'],
    [27, 'overweight'],
    [32, 'obese'],
  ])('BMI %s → %s', (bmi, band) => {
    expect(bmiBand(bmi)).toBe(band)
  })
  it('returns null for null input', () => {
    expect(bmiBand(null)).toBeNull()
  })
})

describe('suggestedTargetWeightKg', () => {
  const base = (goals: string[], weightKg = 80) =>
    ({ profile: { weightKg }, goals: { selected: goals } }) as unknown as OnboardingWizardState

  it('suggests 7% cut for LOSE_FAT', () => {
    expect(suggestedTargetWeightKg(base(['LOSE_FAT']))).toBeCloseTo(74.4, 0)
  })

  it('suggests 3% surplus for BUILD_MUSCLE', () => {
    expect(suggestedTargetWeightKg(base(['BUILD_MUSCLE']))).toBeCloseTo(82.4, 0)
  })

  it('returns null when no weight-related goal selected', () => {
    expect(suggestedTargetWeightKg(base(['MORE_ENERGY']))).toBeNull()
  })

  it('returns null when weightKg is missing', () => {
    expect(suggestedTargetWeightKg(base(['LOSE_FAT'], undefined as unknown as number))).toBeNull()
