describe('autoRankTop3', () => {
  it('respects static priority order', () => {
    expect(autoRankTop3(['BUILD_MUSCLE', 'LOSE_FAT', 'MORE_ENERGY'])).toEqual([
      'LOSE_FAT', 'BUILD_MUSCLE', 'MORE_ENERGY',
    ])
  })

  it('returns at most 3 goals', () => {
