    expect(autoRankTop3(many)).toHaveLength(3)
  })

  it('returns empty array for empty input', () => {
    expect(autoRankTop3([])).toEqual([])
  })

  it('handles single goal', () => {
    expect(autoRankTop3(['EAT_BETTER'])).toEqual(['EAT_BETTER'])
  })
})

describe('reconcileRanked', () => {
  it('drops deselected goals from ranked list', () => {
    const result = reconcileRanked(['LOSE_FAT', 'MORE_ENERGY'], ['LOSE_FAT', 'BUILD_MUSCLE', 'MORE_ENERGY'])
    expect(result).not.toContain('BUILD_MUSCLE')
  })

  it('appends newly selected goals at the bottom', () => {
    const result = reconcileRanked(['LOSE_FAT', 'GET_STRONGER'], ['LOSE_FAT'])
    expect(result).toContain('GET_STRONGER')
  })

  it('treats undefined ranked as empty', () => {
    expect(reconcileRanked(['LOSE_FAT'], undefined)).toContain('LOSE_FAT')
  })
})

